  Pc1GlyphCache cache=Pc1GlyphCache.fromMemory(font);reject(()->cache.lookup(new byte[]{65},0,40,provider),"unowned neighboring memory at0x0");check(font.variableReplacement()==0,"actual404660 cursor commit precedes projection fault");check(rowCount[0]==1&&words.rawWord(Pc1OsWords.GLYPH_DC)==0&&words.rawWord(Pc1OsWords.GLYPH_PREVIOUS_FONT)==0&&words.rawWord(Pc1OsWords.GLYPH_BITS)==0,"1600byte outputclear includes all three original GDI DWORDs before first mono read");check(memory.readAddress(0x48cf48)==0x6b&&memory.readAddress(0x48cf4c)==0x6b,"fault prevents later cache key/size stores");check(memory.readAddress(0x48cf50)==0&&memory.readAddress(0x48d58f)==0,"clear prefix retains original known-memory writes through neighboring owners");return checks;
